// Normalizes the request no matter how it arrived: the Webhook node wraps the
// POSTed JSON in `body`, while the manual Sample video item is already flat.
const item = $input.first().json;
const src = item && typeof item.body === 'object' && item.body !== null ? item.body : item;
const receivedVia = item && typeof item.body === 'object' && item.body !== null ? 'webhook' : 'manual-test';

const clean = (v, max) => String(v == null ? '' : v).replace(/\s+/g, ' ').trim().slice(0, max);

let videoUrl = clean(src.videoUrl || src.url || src.video_url, 2048);
const title = clean(src.title, 160);
const layoutIn = clean(src.layout, 8).toLowerCase();
const layout = layoutIn === 'fit' || layoutIn === 'fill' ? layoutIn : '';

if (!videoUrl) {
  throw new Error('This workflow needs a direct video URL. Expected POST body: { "videoUrl": "https://…/talk.mp4", "title": "optional", "layout": "fill | fit (optional)" }');
}

// A Google Drive share link is a viewer page, not a download. Rewrite the two
// common shapes into the direct-download form; everything else passes through
// untouched.
let sourceKind = 'direct';
const driveFile = /drive\.google\.com\/file\/d\/([-\w]{10,})/.exec(videoUrl);
const driveId = /drive\.google\.com\/(?:open|uc)\?[^#]*\bid=([-\w]{10,})/.exec(videoUrl);
if (driveFile || driveId) {
  videoUrl = 'https://drive.google.com/uc?export=download&id=' + (driveFile ? driveFile[1] : driveId[1]);
  sourceKind = 'google-drive';
}

if (!/^https:\/\//i.test(videoUrl)) {
  throw new Error('videoUrl must be an https URL that returns the video file itself. Got: ' + videoUrl.slice(0, 120));
}

const host = (/^https:\/\/([^/?#]+)/i.exec(videoUrl) || ['', ''])[1].toLowerCase().replace(/:\d+$/, '');
const isPage = host === 'youtu.be' || host === 'youtube.com' || host.endsWith('.youtube.com')
  || host === 'vimeo.com' || host.endsWith('.vimeo.com')
  || host === 'tiktok.com' || host.endsWith('.tiktok.com');
if (isPage) {
  throw new Error('"' + host + '" serves a watch PAGE, not a video file — this workflow cannot download from it. Export or upload the video somewhere that returns the MP4 directly (Google Drive share link, S3/R2 object, your own CDN) and post that URL instead.');
}

return [{ json: { videoUrl, title, layout, sourceKind, host, receivedVia } }];

// Turns one ElevenLabs Scribe response into a clean word stream plus the
// indexed transcript the highlight picker reads. Scribe's word list is the
// only source of timing in this workflow, so the parse stays defensive: the
// field names are checked in a couple of shapes and anything without a usable
// start/end is dropped rather than silently desyncing the captions.
const cfg = $('Config').first().json;
const req = $('Video request').first().json;
const res = $input.first().json || {};

const raw = (Array.isArray(res.words) && res.words)
  || (res.transcription && Array.isArray(res.transcription.words) && res.transcription.words)
  || (Array.isArray(res.results) && res.results[0] && Array.isArray(res.results[0].words) && res.results[0].words)
  || [];

// Curly quotes and dashes survive transcription and then wreck word splitting
// and the caption renderer's metrics. Normalise to ASCII once, here.
const toAscii = (s) => String(s == null ? '' : s)
  .replace(/[‘’ʼ]/g, "'")
  .replace(/[“”]/g, '"')
  .replace(/[–—]/g, '-')
  .replace(/…/g, '...')
  .replace(/\s+/g, ' ')
  .trim();

const words = [];
for (const w of raw) {
  if (!w || typeof w !== 'object') continue;
  const kind = String(w.type == null ? 'word' : w.type).toLowerCase();
  if (kind === 'spacing' || kind === 'audio_event') continue;
  const text = toAscii(w.text != null ? w.text : w.word);
  const start = Number(w.start != null ? w.start : w.start_time);
  const end = Number(w.end != null ? w.end : w.end_time);
  if (!text || !/[\p{L}\p{N}]/u.test(text)) continue;
  if (!Number.isFinite(start) || !Number.isFinite(end) || end <= start) continue;
  words.push({ text, start, end });
}
words.sort((a, b) => a.start - b.start);

if (words.length < 12) {
  throw new Error(
    'The transcription came back with ' + words.length + ' usable words. Scribe needs a media file with speech: check that the xi-api-key credential is attached, that the URL really returned video (a Google Drive virus-scan interstitial returns HTML, not media) and that the MP4 keeps its moov atom at the front. Response head: '
    + JSON.stringify(res).slice(0, 300)
  );
}

const transcriptSeconds = Math.round(words[words.length - 1].end * 100) / 100;
const wps = transcriptSeconds > 0 ? words.length / transcriptSeconds : 2.8;

const clamp = (n, lo, hi) => Math.min(hi, Math.max(lo, n));
const clipCount = clamp(Math.round(Number(cfg.clipCount) || 2), 1, 3);
const clipSeconds = clamp(Number(cfg.clipSeconds) || 28, 12, 45);
const targetWords = Math.max(20, Math.round(clipSeconds * wps));

// Only the transcribed window can be clipped, so the picker is shown exactly
// what exists — no invented ranges. Fifteen words per line keeps the index
// arithmetic obvious to the model.
const MAX_PROMPT_WORDS = 2600;
const shown = words.slice(0, MAX_PROMPT_WORDS);
const lines = [];
for (let i = 0; i < shown.length; i += 15) {
  lines.push('[' + i + '] ' + shown.slice(i, i + 15).map((w) => w.text).join(' '));
}

const promptText = [
  'You are picking short-form vertical highlights from a longer video.',
  '',
  'Return JSON only, in exactly this shape:',
  '{"clips":[{"startWord":0,"endWord":80,"title":"...","whyItWorks":"..."}]}',
  '',
  'Rules:',
  '- Pick exactly ' + clipCount + ' clip' + (clipCount === 1 ? '' : 's') + '.',
  '- startWord and endWord are the [index] numbers in the transcript below. endWord must be greater than startWord.',
  '- This speaker averages ' + wps.toFixed(1) + ' words per second, so aim for about ' + targetWords + ' words per clip (~' + clipSeconds + ' seconds).',
  '- Clips must not overlap.',
  '- Start on the first word of a sentence and end on the last word of a sentence so the clip stands alone with no missing setup.',
  '- Prefer a clear claim, a story beat, a number or a strong opinion. Skip intros, sponsor reads, admin and cross-talk.',
  '- "title" is at most 6 words. No quotes, no emoji, no hashtags, no trailing period — it is burned on screen in large type.',
  '- "whyItWorks" is one short sentence for the person reviewing the run.',
  '',
  req.title ? 'Video title: ' + req.title : 'Video title: (not provided)',
  'Transcript covers the first ' + transcriptSeconds.toFixed(1) + ' seconds of the video, ' + shown.length + ' words:',
  '',
].concat(lines).join('\n');

return [{
  json: {
    words,
    wordCount: words.length,
    promptWords: shown.length,
    transcriptSeconds,
    wordsPerSecond: Math.round(wps * 100) / 100,
    targetWords,
    promptText,
    llmModel: String(cfg.llmModel || 'google/gemini-2.5-flash'),
    transcriptTruncated: words.length > shown.length,
  },
}];

// Turns the picker's word indices into real clip windows.
//
// Everything here is arithmetic on the Scribe word stream, so the clip
// boundaries land on actual spoken words rather than on a guess: the model
// only chooses WHICH words, never the timestamps. A clip that comes back too
// short or too long is grown or trimmed one word at a time, which keeps both
// ends on a word boundary.
const cfg = $('Config').first().json;
const req = $('Video request').first().json;
const tr = $('Read transcript').first().json;
const res = $input.first().json || {};

const clamp = (n, lo, hi) => Math.min(hi, Math.max(lo, n));
const round = (n) => Math.round(n * 100) / 100;
const words = Array.isArray(tr.words) ? tr.words : [];
if (words.length < 12) throw new Error('The transcript reaching Prepare clips has no words.');

const clipCount = clamp(Math.round(Number(cfg.clipCount) || 2), 1, 3);
const target = clamp(Number(cfg.clipSeconds) || 28, 12, 45);
const minSec = clamp(Number(cfg.minClipSeconds) || 15, 6, target);
const maxSec = clamp(Number(cfg.maxClipSeconds) || 40, target, 60);
const LEAD_IN = 0.3;
const TAIL_OUT = 0.45;
const transcriptEnd = words[words.length - 1].end;

const content = res && res.choices && res.choices[0] && res.choices[0].message
  ? res.choices[0].message.content
  : null;

let picked = [];
if (content) {
  let parsed = null;
  try {
    parsed = JSON.parse(content);
  } catch (e) {
    const m = /\{[\s\S]*\}/.exec(String(content));
    if (m) { try { parsed = JSON.parse(m[0]); } catch (e2) { parsed = null; } }
  }
  if (parsed && Array.isArray(parsed.clips)) picked = parsed.clips;
  else if (Array.isArray(parsed)) picked = parsed;
}

const clean = (v, max) => String(v == null ? '' : v).replace(/\s+/g, ' ').trim().slice(0, max);
const sixWords = (s) => clean(s, 120).split(' ').slice(0, 6).join(' ').replace(/[."'’]+$/, '');

const ranges = [];
for (const c of picked) {
  if (!c || typeof c !== 'object') continue;
  let a = Math.round(Number(c.startWord != null ? c.startWord : c.start_word));
  let b = Math.round(Number(c.endWord != null ? c.endWord : c.end_word));
  if (!Number.isFinite(a) || !Number.isFinite(b)) continue;
  a = clamp(a, 0, words.length - 2);
  b = clamp(b, a + 1, words.length - 1);
  ranges.push({ a, b, title: sixWords(c.title || c.hook), why: clean(c.whyItWorks || c.why || c.reason, 200) });
}

// The picker failed, returned prose, or named ranges that do not exist. Split
// the transcribed window evenly instead of failing the run — a mechanical clip
// is still a clip, and the summary says the fallback fired.
let usedFallback = false;
if (!ranges.length) {
  usedFallback = true;
  const per = Math.floor(words.length / clipCount);
  for (let i = 0; i < clipCount; i += 1) {
    const a = i * per;
    const b = Math.min(words.length - 1, (i + 1) * per - 1);
    if (b > a) ranges.push({ a, b, title: '', why: 'Automatic split — the highlight picker returned nothing usable.' });
  }
}

for (const r of ranges) {
  while (words[r.b].end - words[r.a].start < minSec && r.b < words.length - 1) r.b += 1;
  while (words[r.b].end - words[r.a].start > maxSec && r.b > r.a + 1) r.b -= 1;
}

ranges.sort((x, y) => x.a - y.a);
const kept = [];
let lastEnd = -1;
for (const r of ranges) {
  if (r.a <= lastEnd) continue;
  if (words[r.b].end - words[r.a].start < 4) continue;
  kept.push(r);
  lastEnd = r.b;
  if (kept.length >= clipCount) break;
}
if (!kept.length) {
  throw new Error('No usable highlight survived: the picker returned ' + picked.length + ' range(s) and none covered more than four seconds of speech. Try a longer maxTranscribeMB or a stronger llmModel.');
}

return kept.map((r, i) => {
  const startTime = round(Math.max(0, words[r.a].start - LEAD_IN));
  const endTime = round(Math.min(transcriptEnd + TAIL_OUT, words[r.b].end + TAIL_OUT));
  const slice = words.slice(r.a, r.b + 1).map((w) => ({
    text: w.text,
    start: round(Math.max(0, w.start - startTime)),
    end: round(Math.max(0.05, w.end - startTime)),
  }));
  const title = r.title || sixWords(slice.slice(0, 6).map((w) => w.text).join(' '));
  return {
    json: {
      index: i + 1,
      clipCount: kept.length,
      title,
      whyItWorks: r.why,
      startTime,
      endTime,
      seconds: round(endTime - startTime),
      words: slice,
      videoUrl: req.videoUrl,
      sourceTitle: req.title,
      layout: req.layout,
      pickedByModel: !usedFallback,
    },
  };
});

// === buildShortsClip — identical to the frame-reviewed standalone builder ===
// One highlight clip -> one 1080x1920 Zvid project. The source video is trimmed
// in SOURCE time with videoBegin/videoEnd, so nothing is re-encoded or
// re-uploaded: the render farm seeks straight into the original URL.
function buildShortsClip(config, clip) {
  const cfg = config || {};

  const clean = (v) => String(v == null ? '' : v).replace(/\s+/g, ' ').trim();
  const round = (n) => Math.round(n * 100) / 100;
  const clamp = (n, lo, hi) => Math.min(hi, Math.max(lo, n));
  // Sheet / LLM / webhook text is untrusted — everything that reaches html or
  // customCode goes through this first.
  const esc = (s) => String(s).replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
  const hexRgb = (hex, fallback) => {
    const m = /^#?([0-9a-f]{6})$/i.exec(String(hex || '').trim());
    const h = m ? m[1] : fallback;
    return [parseInt(h.slice(0, 2), 16), parseInt(h.slice(2, 4), 16), parseInt(h.slice(4, 6), 16)].join(',');
  };

  const videoUrl = clean(clip.videoUrl);
  if (!videoUrl) throw new Error('The clip has no source videoUrl.');

  const startTime = Math.max(0, Number(clip.startTime) || 0);
  const endTime = Number(clip.endTime);
  if (!Number.isFinite(endTime) || endTime <= startTime) {
    throw new Error('Clip ' + (clip.index || 1) + ' has an empty time window (' + startTime + 's -> ' + endTime + 's).');
  }
  const seconds = round(endTime - startTime);

  const index = Math.max(1, Number(clip.index) || 1);
  const clipCount = Math.max(index, Number(clip.clipCount) || 1);

  // ---- brand knobs --------------------------------------------------------
  const accent = clean(cfg.brandAccent) || '#FFD84D';
  const ink = clean(cfg.brandInk) || '#08090D';
  const titleFont = clean(cfg.titleFont) || 'Anton';
  const uiFont = clean(cfg.uiFont) || 'Montserrat';
  // Clamped because a pasted URL in the handle field would otherwise run off
  // both sides of the canvas.
  const handle = clean(cfg.handle).slice(0, 32);
  const accentRgb = hexRgb(accent, 'FFD84D');
  const inkRgb = hexRgb(ink, '08090D');

  // A clip-level layout override (from the webhook body) beats the Config
  // default, because the right answer depends on the SOURCE framing, not on
  // the account. "fit" is the default: without face tracking a blind centre
  // crop decapitates two-shots, screen shares and anything off-centre.
  const layout = (clean(clip.layout) || clean(cfg.layout) || 'fit').toLowerCase() === 'fill' ? 'fill' : 'fit';

  // ---- title --------------------------------------------------------------
  // The model is asked for <= 6 words, but a model is not a contract: clamp
  // here too so the layout can never be blown out by a long headline.
  const rawTitle = clean(clip.title);
  const titleWords = rawTitle ? rawTitle.split(' ').slice(0, 6) : [];
  let title = titleWords.join(' ');
  // Over the cap, WHOLE words are dropped from the end and no ellipsis is
  // added. A headline is allowed to be a fragment; a trailing "…" on the frame
  // that has to sell the clip reads as a broken render, and it also eats one of
  // the few characters the viewer actually has time to read. (A single word
  // longer than the cap has no word boundary to cut on, so that one case falls
  // back to a hard slice — `overflow-wrap` keeps it inside the box either way.)
  if (title.length > 64) {
    const kept = [];
    let used = 0;
    for (const w of title.split(' ')) {
      const need = used === 0 ? w.length : used + 1 + w.length;
      if (need > 64) break;
      kept.push(w);
      used = need;
    }
    title = kept.length ? kept.join(' ') : title.slice(0, 64);
  }

  // Greedy wrap estimate calibrated on Anton (condensed display face: an
  // average glyph runs ~0.44em, so 900px fits ~29 characters at 70px).
  const wrapLines = (text, fontPx, boxPx, avgEm) => {
    const perLine = Math.max(6, Math.floor(boxPx / (fontPx * avgEm)));
    let lines = 1;
    let used = 0;
    for (const w of String(text).split(' ')) {
      const need = used === 0 ? w.length : used + 1 + w.length;
      if (need <= perLine) { used = need; continue; }
      lines += 1;
      used = Math.min(w.length, perLine);
    }
    return lines;
  };
  // Step the display size down until the headline fits two lines — a third
  // line would push the type into the video band.
  let titleSize = 78;
  for (const size of [78, 70, 62, 55, 49]) {
    titleSize = size;
    if (wrapLines(title, size, 900, 0.44) <= 2) break;
  }
  const titleLines = title ? wrapLines(title, titleSize, 900, 0.44) : 0;

  // ---- captions -----------------------------------------------------------
  const perCue = Math.max(1, Math.min(6, Number(cfg.captionWordsPerCue ?? 3)));
  const words = (Array.isArray(clip.words) ? clip.words : [])
    .map((w) => ({ text: clean(w.text), start: Number(w.start), end: Number(w.end) }))
    .filter((w) => w.text && Number.isFinite(w.start) && Number.isFinite(w.end) && w.end > w.start)
    .map((w) => ({ text: w.text, start: round(clamp(w.start, 0, seconds)), end: round(clamp(w.end, 0, seconds)) }))
    .filter((w) => w.end > w.start);

  const captions = [];
  // The free plan caps caption cues at 200; three words per cue keeps a 40 s
  // clip near 40 cues, but the slice guards a pathological transcript.
  for (let i = 0; i < words.length && captions.length < 200; i += perCue) {
    const chunk = words.slice(i, i + perCue);
    captions.push({
      start: chunk[0].start,
      end: chunk[chunk.length - 1].end,
      text: chunk.map((w) => w.text).join(' '),
      words: chunk.map((w) => ({ start: w.start, end: w.end, text: w.text })),
    });
  }

  // In box modes ("highlight") the chip behind the spoken word needs a
  // `radius`: without one the renderer draws the chip with the subtitle
  // engine's square box field, which is the same field the outline uses — the
  // spoken word came out doubled and offset, with a bar struck through it (seen
  // on a rendered frame, not guessed). With a radius the chip is drawn as a
  // rounded vector rect behind the glyphs instead, and the outline goes back to
  // being an outline. Box modes then get a thin outline plus padding; every
  // other mode recolours the spoken word and keeps the heavy outline, which is
  // what keeps captions readable over both dark and bright footage.
  const BOX_MODES = ['highlight'];
  const animation = clean(cfg.captionAnimation) || 'karaoke';
  const usesBox = BOX_MODES.indexOf(animation) !== -1;
  const strokeWidth = Math.max(0, Number(cfg.captionStrokeWidth ?? 6));
  const captionSize = clamp(Number(cfg.captionSize ?? 76), 30, 110);

  const subtitle = captions.length
    ? {
      captions,
      animation,
      activeWord: usesBox
        ? { color: ink, background: accent, radius: 12 }
        : { color: accent },
      font: { family: uiFont, size: captionSize, color: '#ffffff', bold: true, transform: 'uppercase' },
      stroke: { color: '#000000', width: usesBox ? Math.min(strokeWidth, 2) : strokeWidth },
      ...(usesBox ? { background: { padding: 14 } } : {}),
      position: 'bottom-center',
      // Bottom-anchored: extra lines grow UPWARD, so the caption block can
      // never slide into the platform's bottom gesture zone (~220 px).
      margin: { x: 90, y: 380 },
      maxWordsPerLine: perCue,
    }
    : null;

  // ---- visuals ------------------------------------------------------------
  const visuals = [];

  // `resize` is measured against the CANVAS, not the element box:
  //   cover   -> fills 1080x1920 and centre-crops the sides off a landscape source
  //   contain -> fits the whole 16:9 frame to 1080 wide, centred (~1080x608)
  // "fit" therefore keeps both speakers in frame and fills the rest of the
  // canvas with a blurred, darkened copy of the same source.
  if (layout === 'fit') {
    visuals.push({
      type: 'VIDEO', src: videoUrl, position: 'center-center', resize: 'cover',
      volume: 0, videoBegin: startTime, videoEnd: endTime,
      // Dark enough that the type on top always wins, light enough that the
      // bed still reads as the footage rather than as black bars. The heavy
      // lifting for type contrast is done by the scrim and the ink wash below,
      // which is why this only trims the highlights: at -20 an already-dim
      // studio source landed at ~1% luminance and the backdrop collapsed into
      // letterboxing, which is the exact thing `fit` exists to avoid.
      filter: { blur: String(clamp(Number(cfg.backdropBlur ?? 6), 1, 40)), brightness: -12, saturate: -18 },
      track: 0, enterBegin: 0, exitEnd: seconds,
    });
    visuals.push({
      type: 'VIDEO', src: videoUrl, position: 'center-center', resize: 'contain',
      // Only ONE copy carries the audio, or the clip plays doubled.
      volume: clamp(Number(cfg.sourceVolume ?? 1), 0, 1), videoBegin: startTime, videoEnd: endTime,
      radius: { tl: 26, tr: 26, bl: 26, br: 26 },
      // Track 2 puts the card ABOVE the scrim, so the darkening only ever
      // touches the blurred backdrop and the clip itself stays untouched.
      track: 2, enterBegin: 0, exitEnd: seconds,
    });
  } else {
    visuals.push({
      type: 'VIDEO', src: videoUrl, position: 'center-center', resize: 'cover',
      volume: clamp(Number(cfg.sourceVolume ?? 1), 0, 1), videoBegin: startTime, videoEnd: endTime,
      track: 0, enterBegin: 0, exitEnd: seconds,
    });
  }

  // Scrims: dark at the top and bottom so the title and captions always have
  // contrast, transparent through the middle so the footage stays the star.
  const topStop = layout === 'fit' ? 0.88 : 0.94;
  const botStop = layout === 'fit' ? 0.9 : 0.96;
  const wash = layout === 'fit' ? 0.26 : 0.12;
  const scrimSvg =
    "<svg width='1080' height='1920' viewBox='0 0 1080 1920' xmlns='http://www.w3.org/2000/svg'>" +
    "<defs><linearGradient id='vtsTop' x1='0' y1='0' x2='0' y2='1'>" +
    "<stop offset='0' stop-color='" + ink + "' stop-opacity='" + topStop + "'/>" +
    "<stop offset='0.55' stop-color='" + ink + "' stop-opacity='" + (topStop * 0.52).toFixed(3) + "'/>" +
    "<stop offset='1' stop-color='" + ink + "' stop-opacity='0'/>" +
    "</linearGradient><linearGradient id='vtsBot' x1='0' y1='0' x2='0' y2='1'>" +
    "<stop offset='0' stop-color='" + ink + "' stop-opacity='0'/>" +
    "<stop offset='0.45' stop-color='" + ink + "' stop-opacity='" + (botStop * 0.62).toFixed(3) + "'/>" +
    "<stop offset='1' stop-color='" + ink + "' stop-opacity='" + botStop + "'/>" +
    '</linearGradient></defs>' +
    "<rect width='1080' height='1920' fill='rgba(" + inkRgb + ',' + wash + ")'/>" +
    "<rect y='0' width='1080' height='640' fill='url(#vtsTop)'/>" +
    "<rect y='1180' width='1080' height='740' fill='url(#vtsBot)'/>" +
    '</svg>';
  visuals.push({ type: 'SVG', width: 1080, height: 1920, track: 1, enterBegin: 0, exitEnd: seconds, svg: scrimSvg });

  // ---- progress hairline --------------------------------------------------
  // Three static SVGs and NO customCode: a translucent rail, one accent bar
  // that the renderer's own `wiperight` enter transition reveals left to right
  // across the clip, and a plain full-width rect that owns the tail.
  //
  // This used to be a customCode CSS animation, and every problem it had came
  // from how customCode is rendered: the engine captures ONE loop as a frame
  // strip and repeats it. That capped a single loop at 15 s (so a long clip had
  // to be cut into segments with a 1 px tonal seam at each joint), and the
  // repeat point could land inside the clip — on two of five reviewed clips the
  // finished bar snapped back to zero on the very LAST frame, the frame a
  // paused player, a preview grid and every cover-image picker hold on.
  // An enter transition is an ffmpeg filter over the element's real timeline
  // instead of a captured strip: no loop, no wrap point, no segments, no length
  // cap, and one element instead of 2n+1. Measured on a rendered clip, the
  // wipe advances linearly (11.7% / 24.3% / 36.7% / 49.3% / 61.7% / 74.3% /
  // 86.7% at the matching fractions of its window).
  const BAR_TAIL = 0.25;
  const showBar = cfg.showProgressBar !== false;
  const accentBarSvg =
    "<svg width='1080' height='10' viewBox='0 0 1080 10' xmlns='http://www.w3.org/2000/svg'><rect width='1080' height='10' fill='" + accent + "'/></svg>";
  if (showBar) {
    // The ground the bar fills in against: visible on dark and bright footage
    // alike, so an empty bar still reads as "this clip has just started".
    visuals.push({
      type: 'SVG', x: 0, y: 0, anchor: 'top-left', width: 1080, height: 10, track: 4,
      enterBegin: 0, exitEnd: seconds,
      svg: "<svg width='1080' height='10' viewBox='0 0 1080 10' xmlns='http://www.w3.org/2000/svg'><rect width='1080' height='10' fill='rgba(255,255,255,0.18)'/></svg>",
    });
    // The wipe finishes BAR_TAIL early. A wipe transition is sampled per frame,
    // so its own last frame lands a fraction short of the full width (measured:
    // 99.3% on a 4 s probe); ending early hands a completed bar over to the
    // static rect below with nothing left to round off.
    const barTail = Math.min(BAR_TAIL, round(seconds / 4));
    visuals.push({
      type: 'SVG', x: 0, y: 0, anchor: 'top-left', width: 1080, height: 10, track: 5,
      enterBegin: 0, enterEnd: round(Math.max(0.1, seconds - barTail)), exitEnd: seconds,
      enterAnimation: 'wiperight',
      svg: accentBarSvg,
    });
    // Terminal-frame guard: a plain rect with no animation in it at all, so the
    // finished bar on the final frame is a fact rather than a timing bet.
    visuals.push({
      type: 'SVG', x: 0, y: 0, anchor: 'top-left', width: 1080, height: 10, track: 6,
      enterBegin: round(Math.max(0, seconds - barTail)), exitEnd: seconds,
      svg: accentBarSvg,
    });
  }

  // ---- chrome type --------------------------------------------------------
  // TEXT has no `margin` field and x/y are ignored under a `position` preset,
  // so every inset element carries explicit coordinates.
  // Frame 0 of a Short IS its thumbnail — it is what a paused scroll, a
  // preview grid and every "cover image" picker show. So the chip, the hook
  // and the handle carry NO entrance animation: they are at full opacity on
  // the very first frame. An entrance fade here costs nothing visually and
  // loses the hook on exactly the frame that has to sell the clip. Motion in
  // this template comes from the footage, the karaoke captions and the
  // progress hairline instead.
  visuals.push({
    type: 'TEXT', x: 540, y: 206, anchor: 'top-center', track: 7,
    enterBegin: 0, exitEnd: seconds,
    style: { color: accent, fontFamily: uiFont },
    html: "<div style=\"display:inline-block; background:rgba(" + inkRgb + ",0.62); border:1.5px solid rgba(" + accentRgb + ",0.72); color:" + accent +
      "; border-radius:999px; padding:12px 32px; font-size:25px; font-weight:800; letter-spacing:6px;\">CLIP " + index + ' OF ' + clipCount + '</div>',
  });

  if (title) {
    visuals.push({
      type: 'TEXT', x: 540, y: 296, width: 900, anchor: 'top-center', track: 8,
      enterBegin: 0, exitEnd: seconds,
      style: { color: '#FFFFFF', fontFamily: titleFont },
      // `overflow-wrap` is the belt to the size ramp's braces: the ramp works
      // on an average-glyph estimate, so a single freakishly long word could
      // still out-run the 900px box without it.
      html: "<div style=\"text-align:center; color:#FFFFFF; font-size:" + titleSize +
        "px; line-height:1.06; letter-spacing:0.5px; text-transform:uppercase; overflow-wrap:break-word; text-shadow:0 10px 44px rgba(" + inkRgb + ',0.92);">' + esc(title) + '</div>',
    });
  }

  if (handle) {
    visuals.push({
      type: 'TEXT', x: 540, y: 1612, anchor: 'top-center', track: 9,
      enterBegin: 0, exitEnd: seconds,
      style: { color: '#FFFFFF', fontFamily: uiFont },
      html: "<div style=\"display:inline-block; text-align:center; background:rgba(" + inkRgb + ",0.5); border-radius:999px; padding:9px 26px; color:rgba(255,255,255,0.9); font-size:28px; font-weight:700; letter-spacing:3px;\">" + esc(handle) + '</div>',
    });
  }

  // ---- payload ------------------------------------------------------------
  // The render API only allows letters, digits, spaces, _ and - in `name`.
  // The TITLE is truncated first and the index appended after, so a headline
  // long enough to hit the 60-character cap can never eat the "-2" that tells
  // two clips of the same video apart, and the trim runs last so a cut through
  // a word cannot leave a trailing hyphen.
  const slugSource = title || clean(clip.sourceTitle) || 'clip';
  const slugBody = ('shorts-' + slugSource)
    .toLowerCase().normalize('NFKD').replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9]+/g, '-').slice(0, 56).replace(/^-+|-+$/g, '');
  const safeName = (slugBody || 'shorts-clip') + '-' + index;

  const payload = {
    name: safeName || 'shorts-clip',
    resolution: 'youtube-short',
    frameRate: Number(cfg.frameRate ?? 30),
    backgroundColor: ink,
    outputFormat: 'mp4',
    scenes: [{ id: 'clip', duration: seconds, backgroundColor: ink, visuals }],
    ...(subtitle ? { subtitle } : {}),
  };

  return {
    payload,
    meta: {
      index,
      clipCount,
      title,
      titleSize,
      titleLines,
      layout,
      sourceUrl: videoUrl,
      sourceTitle: clean(clip.sourceTitle),
      startTime: round(startTime),
      endTime: round(endTime),
      seconds,
      captionCount: captions.length,
      captionWords: words.length,
      progressBar: showBar ? 'wipe' : 'off',
      visualCount: visuals.length,
      whyItWorks: clean(clip.whyItWorks),
    },
  };
}

// === n8n glue ===
const config = $('Config').first().json;
const clips = $input.all();
if (!clips.length) throw new Error('No highlight clips reached the builder.');
return clips.map((item, i) => ({
  json: buildShortsClip(config, item.json),
  pairedItem: { item: i },
}));

// The free validate endpoint runs the exact pipeline a render submission runs,
// so a failure here is a payload bug — surface the field list per clip instead
// of a generic HTTP error.
const built = $('Build project JSON').all();
return $input.all().map((res, i) => {
  const status = res.json.statusCode;
  const body = res.json.body || {};
  const meta = built[i].json.meta;
  if (status !== 200 || body.valid === false) {
    const details = Array.isArray(body.details)
      ? body.details.map((d) => '  - ' + d.field + ': ' + d.message).join('\n')
      : JSON.stringify(body).slice(0, 500);
    throw new Error('Zvid rejected clip ' + meta.index + ' of ' + meta.clipCount + ' (HTTP ' + status + '): ' + (body.message || body.error) + '\n' + details);
  }
  return {
    json: {
      ...built[i].json,
      creditsRequired: body.creditsRequired,
      warnings: body.warnings || [],
      schemaVersion: body.schemaVersion,
    },
    pairedItem: { item: i },
  };
});

// Dry run: everything except the paid renders. Each clip is saved as a draft
// you can open in the editor, and the exact credit cost is quoted per clip and
// as a total. Set dryRun to false in Config to render for real.
const cfg = $('Config').first().json;
const req = $('Video request').first().json;
const tr = $('Read transcript').first().json;
const checked = $('Check validation').all();

// The draft save is best-effort (onError: continue) so a hiccup there never
// hides the rest of the dry-run report.
let drafts = [];
try {
  drafts = $('Save draft to editor').all().map((i) => i.json);
} catch (e) { drafts = []; }

// Hard-coded on purpose: the editor host is not a Config knob, and reading one
// that is not in the Config node would be an undocumented setting.
const editorBase = 'https://editor.zvid.io';
const clips = checked.map((item, i) => {
  const d = item.json;
  const project = drafts[i] && drafts[i].project ? drafts[i].project : null;
  return {
    clip: d.meta.index,
    title: d.meta.title,
    whyItWorks: d.meta.whyItWorks,
    seconds: d.meta.seconds,
    sourceStart: d.meta.startTime,
    sourceEnd: d.meta.endTime,
    layout: d.meta.layout,
    captionCues: d.meta.captionCount,
    creditsRequired: d.creditsRequired,
    warnings: d.warnings,
    draftId: project ? project.id : null,
    editorLink: project && project.id ? editorBase + '/?project=' + project.id : null,
  };
});

return [{
  json: {
    ok: true,
    dryRun: true,
    source: { videoUrl: req.videoUrl, title: req.title, sourceKind: req.sourceKind },
    transcribedSeconds: tr.transcriptSeconds,
    transcriptTruncated: tr.transcriptTruncated,
    clipCount: clips.length,
    creditsRequired: clips.reduce((sum, c) => sum + (Number(c.creditsRequired) || 0), 0),
    clips,
    nextStep: clips.some((c) => c.editorLink)
      ? 'Open each editorLink to preview the clip, then set dryRun to false in Config to render for real.'
      : 'Set dryRun to false in Config to render these clips for real.',
  },
}];

// The render response replaces the item, so glue the jobId back onto the clip.
// An index zip is safe here: same items, same order, no loop yet.
const checked = $('Check validation').all();
return $input.all().map((res, i) => {
  const jobId = res.json.jobId || res.json.id;
  if (!jobId) {
    throw new Error('Render submission returned no jobId: ' + JSON.stringify(res.json).slice(0, 300));
  }
  const { payload, ...rest } = checked[i].json;
  return { json: { ...rest, jobId }, pairedItem: { item: i } };
});

// The status response replaces the item again — zip it back with what entered
// this poll iteration. Wait passes items through unchanged and the status node
// runs once per item in order, so index i pairs correctly on every lap.
const carried = $('Wait').all();
const results = $input.all();

// Clips are independent render jobs and they do NOT finish on the same lap.
// `Render finished?` routes per ITEM, so a per-item "completed" test would send
// the first clip forward on its own: Clips response would answer the webhook
// with a short list, and the later lap's respond call would be swallowed by its
// continueRegularOutput as "already responded". The gate is therefore
// ALL-or-nothing — every item carries the same flag, so the whole batch leaves
// the loop together and the caller gets one answer listing every clip.
// Re-polling a job that has already completed is free and returns the same body.
const allCompleted = results.length > 0 && results.every((r) => r.json.state === 'completed');

return results.map((res, i) => {
  const job = res.json;
  return {
    json: {
      ...carried[i].json,
      state: job.state,
      allCompleted,
      pendingClips: results.filter((r) => r.json.state !== 'completed').length,
      failedReason: job.failedReason || null,
      result: job.result || null,
    },
    pairedItem: { item: i },
  };
});

// Fails fast on a failed render and stops the poll loop at the timeout.
// Clips are independent jobs, so the message names which one died.
const cfg = $('Config').first().json;
for (const item of $input.all()) {
  if (item.json.state === 'failed') {
    throw new Error('Render failed for clip ' + item.json.meta.index + ' of ' + item.json.meta.clipCount
      + ' ("' + item.json.meta.title + '"): ' + (item.json.failedReason || 'no reason given'));
  }
}
const maxPolls = Math.ceil((Number(cfg.timeoutMinutes || 20) * 60) / Number(cfg.pollSeconds || 10));
if ($runIndex + 1 >= maxPolls) {
  throw new Error('Renders did not finish within ' + cfg.timeoutMinutes + ' minutes. Long clips from a large source take longer — raise timeoutMinutes in Config.');
}
return $input.all();

// One item per finished clip: this is what ▶ Watch video downloads and what
// Clips response turns into the webhook body.
const cfg = $('Config').first().json;
const req = $('Video request').first().json;
const tr = $('Read transcript').first().json;

return $input.all().map((item, i) => {
  const d = item.json;
  const url = typeof d.result === 'string' ? d.result : (d.result ? d.result.url : null);
  return {
    json: {
      rendered: true,
      clip: d.meta.index,
      of: d.meta.clipCount,
      title: d.meta.title,
      whyItWorks: d.meta.whyItWorks,
      videoUrl: url,
      jobId: d.jobId,
      sourceStart: d.meta.startTime,
      sourceEnd: d.meta.endTime,
      clipSeconds: d.meta.seconds,
      layout: d.meta.layout,
      captionCues: d.meta.captionCount,
      creditsCharged: d.creditsRequired,
      sourceUrl: req.videoUrl,
      sourceTitle: req.title,
      transcribedSeconds: tr.transcriptSeconds,
      handle: cfg.handle,
    },
    pairedItem: { item: i },
  };
});

// Collapses the per-clip items into ONE webhook body. The caller posted a
// single video and gets a single JSON answer back listing every clip.
const req = $('Video request').first().json;
const tr = $('Read transcript').first().json;
const clips = $input.all().map((i) => i.json);

return [{
  json: {
    ok: true,
    dryRun: false,
    source: { videoUrl: req.videoUrl, title: req.title, sourceKind: req.sourceKind },
    transcribedSeconds: tr.transcriptSeconds,
    transcriptTruncated: tr.transcriptTruncated,
    clipCount: clips.length,
    creditsCharged: clips.reduce((sum, c) => sum + (Number(c.creditsCharged) || 0), 0),
    clips: clips.map((c) => ({
      clip: c.clip,
      title: c.title,
      videoUrl: c.videoUrl,
      seconds: c.clipSeconds,
      sourceStart: c.sourceStart,
      sourceEnd: c.sourceEnd,
      jobId: c.jobId,
    })),
  },
}];
